// Keywords to search across all UN portals
// Adjust these to match the exact roles you want
const searchTerms = [
  { keywords: 'data science',           portal: 'both' },
  { keywords: 'machine learning',       portal: 'both' },
  { keywords: 'data analyst',           portal: 'both' },
  { keywords: 'information management', portal: 'both' },
  { keywords: 'statistics',             portal: 'inspira' }
];

return searchTerms.map(s => ({ json: s }));

// PeopleSoft requires extracting the session token (ICSID) and state number
// from the initial page HTML before any search POST will be accepted
const html     = $input.item.json.data || '';
const keywords = $('Search Keywords').item.json.keywords;

// Extract ICSID — hidden input field PeopleSoft embeds on every page
const icsidMatch   = html.match(/name=["']ICSID["'][^>]*value=["']([^"']+)["']/) ||
                     html.match(/value=["']([^"']+)["'][^>]*name=["']ICSID["']/);
const icsid        = icsidMatch ? icsidMatch[1] : '';

// Extract ICStateNum — increments with each page interaction
const stateMatch   = html.match(/name=["']ICStateNum["'][^>]*value=["'](\d+)["']/) ||
                     html.match(/value=["'](\d+)["'][^>]*name=["']ICStateNum["']/);
const icStateNum   = stateMatch ? stateMatch[1] : '1';

// Extract any PT_SELECTOR_BTN or similar tokens (varies by PeopleSoft version)
const selectorMatch = html.match(/name=["']PT_SELECTOR_BTN["'][^>]*value=["']([^"']*)["']/);
const selectorBtn   = selectorMatch ? selectorMatch[1] : '';

if (!icsid) {
  // Session extraction failed — Inspira may require login or has changed its structure
  return [{ json: {
    error: 'ICSID not found — Inspira may require authentication or the page structure changed.',
    html_snippet: html.slice(0, 500),
    keywords
  }}];
}

return [{ json: { icsid, icStateNum, selectorBtn, keywords } }];

// Parse PeopleSoft HRS job search results page
// PeopleSoft renders jobs in a grid with predictable ID patterns:
//   HRS_CE_ILJ_I_GBL_HRS_POSITION_TITLE_I$0  ← job title (row 0)
//   HRS_CE_ILJ_I_GBL_HRS_POSITION_TITLE_I$1  ← row 1 etc.
const html     = $input.item.json.data || '';
const keywords = $('Extract Inspira Session Token').item.json.keywords;
const jobs     = [];

// Pattern 1: PeopleSoft field IDs for title (standard HRS component)
const titlePattern = /id="HRS_CE_ILJ_I_GBL_HRS_POSITION_TITLE_I\$(\d+)"[^>]*>([^<]+)<\/a>/g;
let m;
while ((m = titlePattern.exec(html)) !== null) {
  const rowIdx = m[1];
  const title  = m[2].trim();

  // Extract matching row fields using the same row index
  const deptRx   = new RegExp(`id="HRS_CE_ILJ_I_GBL_HRS_ORG_NAME_SRCH\\$${rowIdx}"[^>]*>([^<]+)<`);
  const locRx    = new RegExp(`id="HRS_CE_ILJ_I_GBL_DERIVE_LOC_DESCR\\$${rowIdx}"[^>]*>([^<]+)<`);
  const dateRx   = new RegExp(`id="HRS_CE_ILJ_I_GBL_HRS_JO_POSTED_DT\\$${rowIdx}"[^>]*>([^<]+)<`);
  const jobIdRx  = new RegExp(`id="HRS_CE_ILJ_I_GBL_HRS_JO_REQ_NO_I\\$${rowIdx}"[^>]*>([^<]+)<`);
  const linkRx   = new RegExp(`id="HRS_CE_ILJ_I_GBL_HRS_POSITION_TITLE_I\\$${rowIdx}"\\s+href="([^"]+)"`);

  const dept     = (html.match(deptRx)  || [])[1]?.trim() || 'UN Secretariat';
  const location = (html.match(locRx)   || [])[1]?.trim() || 'Various';
  const posted   = (html.match(dateRx)  || [])[1]?.trim() || '';
  const jobNo    = (html.match(jobIdRx) || [])[1]?.trim() || `UN-ROW-${rowIdx}`;
  const linkPath = (html.match(linkRx)  || [])[1] || '';
  const jobUrl   = linkPath ? `https://inspira.un.org${linkPath}` : 'https://inspira.un.org/psc/PUNA1J/EMPLOYEE/HRMS/c/HRS_HRAM.HRS_APP_SCHJOB.GBL';

  jobs.push({
    json: {
      job_id:         `UN-${jobNo.replace(/\s+/g, '')}`,
      title,
      company:        dept,
      location,
      posted_date:    posted,
      job_url:        jobUrl,
      search_query:   keywords,
      matched_skills: '',
      relevance_score: 0,
      date_found:     new Date().toISOString().split('T')[0],
      source:         'UN Inspira'
    }
  });
}

// Pattern 2 fallback — generic link + text extraction if PeopleSoft IDs differ
if (jobs.length === 0) {
  const linkPattern = /href="([^"]*HRS_APP_JBPST[^"]*)">([^<]{10,100})<\/a>/g;
  while ((m = linkPattern.exec(html)) !== null) {
    const href  = m[1];
    const title = m[2].trim();
    if (title && !title.includes('class=')) {
      jobs.push({
        json: {
          job_id:          'UN-' + href.replace(/[^a-z0-9]/gi, '').slice(-10),
          title,
          company:         'UN Secretariat',
          location:        'Various',
          posted_date:     '',
          job_url:         href.startsWith('http') ? href : 'https://inspira.un.org' + href,
          search_query:    keywords,
          matched_skills:  '',
          relevance_score: 0,
          date_found:      new Date().toISOString().split('T')[0],
          source:          'UN Inspira'
        }
      });
    }
  }
}

if (jobs.length === 0) {
  return [{ json: {
    job_id: null, title: 'No Inspira results parsed',
    company: 'UN', location: null, posted_date: null,
    job_url: 'https://inspira.un.org/psc/PUNA1J/EMPLOYEE/HRMS/c/HRS_HRAM.HRS_APP_SCHJOB.GBL',
    search_query: keywords, matched_skills: '', relevance_score: 0,
    date_found: new Date().toISOString().split('T')[0],
    source: 'UN Inspira',
    note: 'Session may require cookies or Inspira changed its HTML structure. Check html_length.',
    html_length: html.length
  }}];
}

return jobs;

// Parse unjobs.org search results
// unjobs.org is a UN job aggregator covering 50+ UN agencies
const html     = $input.item.json.data || '';
const keywords = $('Search Keywords').item.json.keywords;
const jobs     = [];

// unjobs.org renders job cards in article/div blocks with class 'jobad'
// Typical structure:
//   <h3 class="job-title"><a href="/duty_stations/...slug">Title</a></h3>
//   <span class="organization">UNICEF</span>
//   <span class="duty-station">Nairobi, Kenya</span>
//   <span class="deadline">2024-01-31</span>

// Pattern A: job title links
const cardPattern = /<h[23][^>]*>[\s]*<a[^>]+href="(\/[^"]+)"[^>]*>([^<]{5,120})<\/a>[\s]*<\/h[23]>/g;
const orgPattern  = /<(?:span|div)[^>]*class="[^"]*(?:organization|agency|org)[^"]*"[^>]*>([^<]+)<\/(?:span|div)>/g;
const locPattern  = /<(?:span|div)[^>]*class="[^"]*(?:duty.station|location|place)[^"]*"[^>]*>([^<]+)<\/(?:span|div)>/g;
const datePattern = /<(?:span|div|time)[^>]*class="[^"]*(?:deadline|closing|date)[^"]*"[^>]*>([^<]+)<\/(?:span|div|time)>/g;

const titleMatches = [...html.matchAll(/<h[23][^>]*>[\s]*<a[^>]+href="(\/[^"]+)"[^>]*>([^<]{5,120})<\/a>[\s]*<\/h[23]>/g)];
const orgMatches   = [...html.matchAll(/<(?:span|div)[^>]*class="[^"]*(?:organization|agency|org)[^"]*"[^>]*>([^<]+)<\/(?:span|div)>/g)];
const locMatches   = [...html.matchAll(/<(?:span|div)[^>]*class="[^"]*(?:duty.station|location|place)[^"]*"[^>]*>([^<]+)<\/(?:span|div)>/g)];
const dateMatches  = [...html.matchAll(/<(?:span|div|time)[^>]*class="[^"]*(?:deadline|closing|date)[^"]*"[^>]*>([^<]+)<\/(?:span|div|time)>/g)];

for (let i = 0; i < titleMatches.length; i++) {
  const href  = titleMatches[i][1];
  const title = titleMatches[i][2].trim();
  const org   = orgMatches[i]   ? orgMatches[i][1].trim()   : 'UN Agency';
  const loc   = locMatches[i]   ? locMatches[i][1].trim()   : 'Various';
  const date  = dateMatches[i]  ? dateMatches[i][1].trim()  : '';

  jobs.push({
    json: {
      job_id:          'UNJOBS-' + href.replace(/[^a-z0-9]/gi, '').slice(0, 20),
      title,
      company:         org,
      location:        loc,
      posted_date:     date,
      job_url:         `https://unjobs.org${href}`,
      search_query:    keywords,
      matched_skills:  '',
      relevance_score: 0,
      date_found:      new Date().toISOString().split('T')[0],
      source:          'unjobs.org (UN Aggregator)'
    }
  });
}

if (jobs.length === 0) {
  // Fallback: try simpler anchor pattern — any link with /duty_stations/ path
  const altMatches = [...html.matchAll(/href="(\/duty_stations\/[^"]+)">([^<]{5,120})<\/a>/g)];
  for (const m of altMatches) {
    const title = m[2].replace(/&amp;/g, '&').trim();
    jobs.push({
      json: {
        job_id:          'UNJOBS-' + m[1].replace(/[^a-z0-9]/gi, '').slice(0, 20),
        title,
        company:         'UN Agency',
        location:        'Various',
        posted_date:     '',
        job_url:         `https://unjobs.org${m[1]}`,
        search_query:    keywords,
        matched_skills:  '',
        relevance_score: 0,
        date_found:      new Date().toISOString().split('T')[0],
        source:          'unjobs.org (UN Aggregator)'
      }
    });
  }
}

if (jobs.length === 0) {
  return [{ json: {
    job_id: null, title: 'No unjobs.org results parsed', company: 'UN', location: null,
    posted_date: null, job_url: `https://unjobs.org/search?criteria=${encodeURIComponent(keywords)}`,
    search_query: keywords, matched_skills: '', relevance_score: 0,
    date_found: new Date().toISOString().split('T')[0],
    source: 'unjobs.org (UN Aggregator)',
    note: 'HTML structure may have changed. Check html_length.',
    html_length: html.length
  }}];
}

return jobs;
